{
    var arg = getEvaluatedArgumentByKeyString(keystring);
    switch(arg.type) {
        case 'Expression':
            try {
                // try to evaluate script
                var jsEval = eval(arg.value);
                return jsEval;
            } catch (e) {
                // if error, just return the value of the evaluated argument
                return arg.value;
            }
        default:
            return arg.value;
    }
}

